2	 * PearlOS QA Screenshot Script
3	 *
4	 * Authenticates against the Dashboard login, waits for the ActiveJobsWidget,
5	 * captures a timestamped screenshot of the widget, and saves it to
6	 * /qa/screenshots/.
7	 *
8	 * Environment variables (read from .env.local by default):
9	 *   DASHBOARD_ADMIN_EMAIL    - login email
10	 *   DASHBOARD_ADMIN_PASSWORD - login password
11	 *   PEARLOS_URL              - base URL (default: http://localhost:3000)
12	 *
13	 * Usage:
14	 *   npx tsx scripts/qa-screenshot.ts
15	 */
16	
17	import { chromium, type Page } from 'playwright';
18	import * as fs from 'fs';
19	import * as path from 'path';
20	import * as dotenv from 'dotenv';
21	
22	// Load env
23	dotenv.config({ path: path.resolve(__dirname, '..', '.env.local') });
24	
25	const BASE_URL = process.env.PEARLOS_URL || 'http://localhost:3000';
26	const EMAIL = process.env.DASHBOARD_ADMIN_EMAIL;
27	const PASSWORD = process.env.DASHBOARD_ADMIN_PASSWORD;
28	const SCREENSHOTS_DIR = path.resolve(__dirname, '..', 'qa', 'screenshots');
29	
30	async function authenticate(page: Page): Promise<void> {
31	  if (!EMAIL || !PASSWORD) {
32	    throw new Error(
33	      'Missing DASHBOARD_ADMIN_EMAIL or DASHBOARD_ADMIN_PASSWORD in environment',
34	    );
35	  }
36	
37	  // Dashboard login lives at /dashboard/login
38	  await page.goto(`${BASE_URL}/dashboard/login`, { waitUntil: 'networkidle', timeout: 30_000 });
39	
40	  // The login form uses React Hook Form with placeholder-based inputs.
41	  // Target by placeholder text which is stable across renders.
42	  const emailInput = page.locator('input[placeholder="Username or Email"]');
43	  const passwordInput = page.locator('input[placeholder="****"]');
44	
45	  await emailInput.waitFor({ state: 'visible', timeout: 15_000 });
46	  await emailInput.fill(EMAIL);
47	  await passwordInput.fill(PASSWORD);
48	
49	  // Submit via the Sign In button
50	  await page.click('button[type="submit"]');
51	
52	  // Wait for navigation away from /login
53	  await page.waitForURL((url) => !url.pathname.includes('/login'), {
54	    timeout: 30_000,
55	  });
56	
57	  // Extra settle time for React hydration
58	  await page.waitForTimeout(3000);
59	}
60	
61	async function waitForActiveJobsWidget(page: Page): Promise<void> {
62	  // The ActiveJobsWidget injects a <style id="gohufont-active-jobs"> tag
63	  // when it mounts. We wait for that as a fingerprint.
64	  try {
65	    await page.waitForFunction(
66	      () => !!document.getElementById('gohufont-active-jobs'),
67	      { timeout: 20_000 },
68	    );
69	  } catch {
70	    console.warn(
71	      'ActiveJobsWidget font-face tag not found — widget may not be rendered. Continuing anyway.',
72	    );
73	  }
74	
75	  // Let animations settle
76	  await page.waitForTimeout(2000);
77	}
78	
79	function screenshotFilename(label: string): string {
80	  const ts = new Date().toISOString().replace(/[:.]/g, '-');
81	  const slug = label.replace(/[^a-z0-9]+/gi, '-').toLowerCase();
82	  return `${slug}-${ts}.png`;
83	}
84	
85	async function main() {
86	  fs.mkdirSync(SCREENSHOTS_DIR, { recursive: true });
87	
88	  const browser = await chromium.launch({ headless: true });
89	  const context = await browser.newContext({
90	    viewport: { width: 1280, height: 800 },
91	  });
92	  const page = await context.newPage();
93	
94	  try {
95	    console.log(`Navigating to ${BASE_URL} ...`);
96	
97	    // Authenticate
98	    await authenticate(page);
99	    console.log('Authenticated.');
100	
101	    // Navigate to main page (may already be there after login redirect)
102	    if (!page.url().includes(BASE_URL) || page.url().includes('/login')) {
103	      await page.goto(BASE_URL, { waitUntil: 'networkidle', timeout: 30_000 });
104	    }
105	
106	    // Wait for ActiveJobsWidget
107	    await waitForActiveJobsWidget(page);
108	    console.log('ActiveJobsWidget detected (or timeout reached).');
