1	import { NextRequest, NextResponse } from 'next/server';
2	
3	/**
4	 * /api/discord/send — Send a message to a Discord channel via the bot.
5	 *
6	 * POST /api/discord/send
7	 * Body: { channelId: string, content: string }
8	 *
9	 * Returns JSON: { success: true, messageId: string }
10	 */
11	
12	const DISCORD_API = 'https://discord.com/api/v10';
13	const DEFAULT_CHANNEL_ID = '1471441655650324533'; // #general
14	
15	function getBotToken(): string | null {
16	  try {
17	    const fs = require('fs');
18	    const config = JSON.parse(fs.readFileSync('/root/.openclaw/openclaw.json', 'utf-8'));
19	    return config?.channels?.discord?.token || null;
20	  } catch {
21	    return process.env.DISCORD_BOT_TOKEN || null;
22	  }
23	}
24	
25	export async function POST(req: NextRequest) {
26	  const token = getBotToken();
27	  if (!token) {
28	    return NextResponse.json({ error: 'Discord bot token not configured' }, { status: 500 });
29	  }
30	
31	  let body: any;
32	  try {
33	    body = await req.json();
34	  } catch {
35	    return NextResponse.json({ error: 'Invalid JSON body' }, { status: 400 });
36	  }
37	
38	  const channelId = body.channelId || DEFAULT_CHANNEL_ID;
39	  const content = (body.content || '').trim();
40	
41	  if (!content) {
42	    return NextResponse.json({ error: 'Message content is required' }, { status: 400 });
43	  }
44	
45	  if (content.length > 2000) {
46	    return NextResponse.json({ error: 'Message too long (max 2000 characters)' }, { status: 400 });
47	  }
48	
49	  // Basic channel ID validation (snowflake format)
50	  if (!/^\d{17,20}$/.test(channelId)) {
51	    return NextResponse.json({ error: 'Invalid channel ID' }, { status: 400 });
52	  }
53	
54	  try {
55	    const res = await fetch(`${DISCORD_API}/channels/${channelId}/messages`, {
56	      method: 'POST',
57	      headers: {
58	        Authorization: `Bot ${token}`,
59	        'Content-Type': 'application/json',
60	      },
61	      body: JSON.stringify({ content }),
62	    });
63	
64	    if (!res.ok) {
65	      const text = await res.text();
66	      console.error('[discord/send] Discord API error:', res.status, text);
67	      return NextResponse.json({ error: 'Discord API error', status: res.status }, { status: 502 });
68	    }
69	
70	    const msg = await res.json();
71	    return NextResponse.json({ success: true, messageId: msg.id });
72	  } catch (err: any) {
73	    console.error('[discord/send] Error:', err.message);
74	    return NextResponse.json({ error: 'Failed to send message' }, { status: 500 });
75	  }
76	}
