1	import { NextRequest, NextResponse } from 'next/server';
2	
3	/**
4	 * /api/discord/messages — Fetch recent messages from a Discord channel.
5	 *
6	 * GET /api/discord/messages?channelId=<id>&limit=<n>&before=<messageId>
7	 *
8	 * Returns JSON: { messages: [{ id, content, author, timestamp, attachments, embeds }] }
9	 */
10	
11	const DISCORD_API = 'https://discord.com/api/v10';
12	const DEFAULT_CHANNEL_ID = '1471441655650324533'; // #general
13	
14	function getBotToken(): string | null {
15	  try {
16	    const fs = require('fs');
17	    const config = JSON.parse(fs.readFileSync('/root/.openclaw/openclaw.json', 'utf-8'));
18	    return config?.channels?.discord?.token || null;
19	  } catch {
20	    return process.env.DISCORD_BOT_TOKEN || null;
21	  }
22	}
23	
24	function avatarUrl(userId: string, avatarHash: string | null): string {
25	  if (!avatarHash) {
26	    // Default Discord avatar
27	    const index = (BigInt(userId) >> BigInt(22)) % BigInt(6);
28	    return `https://cdn.discordapp.com/embed/avatars/${index}.png`;
29	  }
30	  const ext = avatarHash.startsWith('a_') ? 'gif' : 'png';
31	  return `https://cdn.discordapp.com/avatars/${userId}/${avatarHash}.${ext}?size=64`;
32	}
33	
34	export async function GET(req: NextRequest) {
35	  const token = getBotToken();
36	  if (!token) {
37	    return NextResponse.json({ error: 'Discord bot token not configured' }, { status: 500 });
38	  }
39	
40	  const channelId = req.nextUrl.searchParams.get('channelId') || DEFAULT_CHANNEL_ID;
41	  const limit = Math.min(Math.max(parseInt(req.nextUrl.searchParams.get('limit') || '50', 10) || 50, 1), 100);
42	  const before = req.nextUrl.searchParams.get('before') || '';
43	
44	  try {
45	    let url = `${DISCORD_API}/channels/${channelId}/messages?limit=${limit}`;
46	    if (before) url += `&before=${before}`;
47	
48	    const res = await fetch(url, {
49	      headers: { Authorization: `Bot ${token}` },
50	    });
51	
52	    if (!res.ok) {
53	      const text = await res.text();
54	      console.error('[discord/messages] Discord API error:', res.status, text);
55	      return NextResponse.json({ error: 'Discord API error', status: res.status }, { status: 502 });
56	    }
57	
58	    const raw = await res.json();
59	
60	    const messages = raw.map((msg: any) => ({
61	      id: msg.id,
62	      content: msg.content || '',
63	      author: {
64	        id: msg.author.id,
65	        username: msg.author.username,
66	        displayName: msg.author.global_name || msg.author.username,
67	        avatar: avatarUrl(msg.author.id, msg.author.avatar),
68	        bot: msg.author.bot || false,
69	      },
70	      timestamp: msg.timestamp,
71	      editedTimestamp: msg.edited_timestamp,
72	      attachments: (msg.attachments || []).map((a: any) => ({
73	        id: a.id,
74	        filename: a.filename,
75	        url: a.url,
76	        contentType: a.content_type,
77	        size: a.size,
78	      })),
79	      embeds: (msg.embeds || []).length,
80	      reactions: (msg.reactions || []).map((r: any) => ({
81	        emoji: r.emoji.name,
82	        count: r.count,
83	      })),
84	      referencedMessage: msg.referenced_message
85	        ? {
86	            id: msg.referenced_message.id,
87	            content: (msg.referenced_message.content || '').slice(0, 120),
88	            author: msg.referenced_message.author?.username || 'Unknown',
89	          }
90	        : null,
91	      type: msg.type, // 0 = default, 19 = reply, etc.
92	    }));
93	
94	    // Discord returns newest first — reverse to oldest-first for the UI
95	    messages.reverse();
96	
97	    return NextResponse.json({ messages, channelId });
98	  } catch (err: any) {
99	    console.error('[discord/messages] Error:', err.message);
100	    return NextResponse.json({ error: 'Failed to fetch messages' }, { status: 500 });
101	  }
102	}
